import * as path from "node:path";
import chalk from "chalk";
import type { Command } from "commander";
import {
  checkSlugUniqueness,
  createNote,
  createTask,
  createTodo,
  deleteTask,
  getAuthor,
  initContext,
  type LoadedSpecItem,
  type LoadedTask,
  loadAllItems,
  loadAllTasks,
  ReferenceIndex,
  saveTask,
  scanTestCoverage,
  syncSpecImplementationStatus,
} from "../../parser/index.js";
import { commitIfShadow } from "../../parser/shadow.js";
import type { Task, TaskInput } from "../../schema/index.js";
import { alignmentCheck, errors } from "../../strings/index.js";
import {
  formatCommitGuidance,
  printCommitGuidance,
} from "../../utils/commit.js";
import { executeBatchOperation, formatBatchOutput } from "../batch.js";
import { EXIT_CODES } from "../exit-codes.js";
import {
  error,
  formatTaskDetails,
  formatTaskList,
  info,
  isJsonMode,
  output,
  success,
  warn,
} from "../output.js";
import { grepItem } from "../../utils/grep.js";

/**
 * Find a task by reference with detailed error reporting.
 * Returns the task or exits with appropriate error.
 */
function resolveTaskRef(
  ref: string,
  tasks: LoadedTask[],
  index: ReferenceIndex,
): LoadedTask {
  const result = index.resolve(ref);

  if (!result.ok) {
    switch (result.error) {
      case "not_found":
        error(errors.reference.taskNotFound(ref));
        break;
      case "ambiguous":
        error(errors.reference.ambiguous(ref));
        for (const candidate of result.candidates) {
          const task = tasks.find((t) => t._ulid === candidate);
          const slug = task?.slugs[0] || "";
          console.error(
            `  - ${index.shortUlid(candidate)} ${slug ? `(${slug})` : ""}`,
          );
        }
        break;
      case "duplicate_slug":
        error(errors.reference.slugMapsToMultiple(ref));
        for (const candidate of result.candidates) {
          console.error(`  - ${index.shortUlid(candidate)}`);
        }
        break;
    }
    // AC: @cli-exit-codes consistent-usage - NOT_FOUND for missing resources
    process.exit(EXIT_CODES.NOT_FOUND);
  }

  // Check if it's actually a task
  const task = tasks.find((t) => t._ulid === result.ulid);
  if (!task) {
    error(errors.reference.notTask(ref));
    // AC: @cli-exit-codes consistent-usage - NOT_FOUND for missing resources
    process.exit(EXIT_CODES.NOT_FOUND);
  }

  return task;
}

/**
 * Batch-compatible resolver that returns null instead of calling process.exit().
 * Used by executeBatchOperation to handle errors without terminating the process.
 * AC: @multi-ref-batch ac-4, ac-8 - Partial failure handling and ref resolution
 */
function resolveTaskRefForBatch(
  ref: string,
  tasks: LoadedTask[],
  index: ReferenceIndex,
): { task: LoadedTask | null; error?: string } {
  const result = index.resolve(ref);

  if (!result.ok) {
    let errorMsg: string;
    switch (result.error) {
      case "not_found":
        errorMsg = `Reference "${ref}" not found`;
        break;
      case "ambiguous":
        errorMsg = `Reference "${ref}" is ambiguous (matches ${result.candidates.length} items)`;
        break;
      case "duplicate_slug":
        errorMsg = `Slug "${ref}" maps to multiple items`;
        break;
    }
    return { task: null, error: errorMsg };
  }

  // Check if it's actually a task
  const task = tasks.find((t) => t._ulid === result.ulid);
  if (!task) {
    return { task: null, error: `Reference "${ref}" is not a task` };
  }

  return { task };
}

/**
 * Helper function to update task fields.
 * Used by both single-ref and batch modes of task set.
 * AC: @spec-task-set-batch ac-1, ac-2, ac-4, ac-5
 */
async function setTaskFields(
  foundTask: LoadedTask,
  ctx: any,
  tasks: LoadedTask[],
  items: LoadedSpecItem[],
  _allMetaItems: any[],
  index: ReferenceIndex,
  options: any,
): Promise<{
  success: boolean;
  message?: string;
  error?: string;
  data?: unknown;
}> {
  try {
    // Check slug uniqueness if adding a new slug
    if (options.slug) {
      const slugCheck = checkSlugUniqueness(
        index,
        [options.slug],
        foundTask._ulid,
      );
      if (!slugCheck.ok) {
        return {
          success: false,
          error: `Slug "${slugCheck.slug}" already exists on ${slugCheck.existingUlid}`,
        };
      }
    }

    // Build updated task with only provided options
    const updatedTask: Task = { ...foundTask };
    const changes: string[] = [];

    if (options.title) {
      updatedTask.title = options.title;
      changes.push("title");
    }

    if (options.specRef) {
      // Validate the spec ref exists and is a spec item
      const specResult = index.resolve(options.specRef);
      if (!specResult.ok) {
        return {
          success: false,
          error: errors.reference.specRefNotFound(options.specRef),
        };
      }
      // Check it's not a task
      const isTask = tasks.some((t) => t._ulid === specResult.ulid);
      if (isTask) {
        return {
          success: false,
          error: errors.reference.specRefIsTask(options.specRef),
        };
      }
      updatedTask.spec_ref = options.specRef;
      changes.push("spec_ref");
    }

    if (options.metaRef) {
      // Validate the meta ref exists and is a meta item
      const metaRefResult = index.resolve(options.metaRef);
      if (!metaRefResult.ok) {
        return {
          success: false,
          error: errors.reference.metaRefNotFound(options.metaRef),
        };
      }

      // Check if the resolved item is a meta item (not a spec item or task)
      const isTask = tasks.some((t) => t._ulid === metaRefResult.ulid);
      const isSpecItem = items.some((i) => i._ulid === metaRefResult.ulid);

      if (isTask || isSpecItem) {
        return {
          success: false,
          error: errors.reference.metaRefPointsToSpec(options.metaRef),
        };
      }

      updatedTask.meta_ref = options.metaRef;
      changes.push("meta_ref");
    }

    if (options.priority) {
      const priority = parseInt(options.priority, 10);
      if (Number.isNaN(priority) || priority < 1 || priority > 5) {
        return {
          success: false,
          error: "Priority must be between 1 and 5",
        };
      }
      updatedTask.priority = priority;
      changes.push("priority");
    }

    if (options.slug) {
      if (!updatedTask.slugs.includes(options.slug)) {
        updatedTask.slugs = [...updatedTask.slugs, options.slug];
        changes.push("slug");
      }
    }

    if (options.tag) {
      const newTags = options.tag.filter(
        (t: string) => !updatedTask.tags.includes(t),
      );
      if (newTags.length > 0) {
        updatedTask.tags = [...updatedTask.tags, ...newTags];
        changes.push("tags");
      }
    }

    if (options.dependsOn) {
      // Validate all dependency refs
      for (const depRef of options.dependsOn) {
        const depResult = index.resolve(depRef);
        if (!depResult.ok) {
          return {
            success: false,
            error: errors.reference.depNotFound(depRef),
          };
        }
        // Ensure the dependency is a task, not a spec item
        const isTask = tasks.some((t) => t._ulid === depResult.ulid);
        if (!isTask) {
          return {
            success: false,
            error: `Reference "${depRef}" is not a task`,
          };
        }
      }
      updatedTask.depends_on = options.dependsOn;
      changes.push("depends_on");
    }

    // AC: @spec-task-clear-deps ac-1, ac-2 - Clear all dependencies
    if (options.clearDeps) {
      if (foundTask.depends_on.length === 0) {
        // AC: @spec-task-clear-deps ac-2 - No changes needed
        return {
          success: true,
          message: "No changes: task has no dependencies to clear",
        };
      }
      updatedTask.depends_on = [];
      changes.push("depends_on");

      // Add note documenting the change
      // AC: @task-set ac-author
      const note = createNote(
        `Dependencies cleared (was: ${foundTask.depends_on.join(", ")})`,
        getAuthor(),
      );
      updatedTask.notes = [...updatedTask.notes, note];
    }

    // AC: @task-automation-eligibility ac-5, ac-11, ac-12, ac-18
    // Handle automation status changes
    // Note: --no-automation sets options.automation to false, so check that first
    if (options.automation === false) {
      // --no-automation flag clears the automation status (AC: ac-12)
      delete updatedTask.automation;
      changes.push("automation");
    } else if (options.automation !== undefined) {
      const validStatuses = ["eligible", "needs_review", "manual_only"];
      if (!validStatuses.includes(options.automation)) {
        return {
          success: false,
          error: `Invalid automation status: ${options.automation}. Must be one of: ${validStatuses.join(", ")}`,
        };
      }

      // AC: @task-automation-eligibility ac-18 - require reason for needs_review
      if (options.automation === "needs_review" && !options.reason) {
        return {
          success: false,
          error:
            "Setting automation to needs_review requires --reason flag explaining why",
        };
      }

      updatedTask.automation = options.automation as
        | "eligible"
        | "needs_review"
        | "manual_only";
      changes.push("automation");

      // If reason provided, add a note documenting the change
      // AC: @task-set ac-author
      if (options.reason) {
        const note = createNote(
          `Automation status set to ${options.automation}: ${options.reason}`,
          getAuthor(),
        );
        updatedTask.notes = [...updatedTask.notes, note];
        changes.push("note");
      }
    }

    // AC: @spec-task-set-batch ac-4 - Warn on no changes, don't fail
    if (changes.length === 0) {
      return {
        success: true,
        message: "No changes specified",
        data: { task: updatedTask },
      };
    }

    await saveTask(ctx, updatedTask);
    await commitIfShadow(
      ctx.shadow,
      "task-set",
      foundTask.slugs[0] || index.shortUlid(foundTask._ulid),
      changes.join(", "),
    );

    return {
      success: true,
      message: `Updated task: ${index.shortUlid(updatedTask._ulid)} (${changes.join(", ")})`,
      data: { task: updatedTask },
    };
  } catch (err) {
    return {
      success: false,
      error: err instanceof Error ? err.message : String(err),
    };
  }
}

/**
 * Register the 'task' command group (singular - operations on individual tasks)
 */
export function registerTaskCommands(program: Command): void {
  const task = program
    .command("task")
    .description("Operations on individual tasks");

  // kspec task list - alias for 'kspec tasks list'
  task
    .command("list")
    .description("List all tasks (alias for 'kspec tasks list')")
    .option("-s, --status <status>", "Filter by status")
    .option("-t, --type <type>", "Filter by type")
    .option("--tag <tag>", "Filter by tag")
    .option("--meta-ref <ref>", "Filter by meta reference")
    .option("-g, --grep <pattern>", "Search content with regex pattern")
    .option("-v, --verbose", "Show more details")
    .option("--full", "Show full details (notes, todos, timestamps)")
    .action(async (options) => {
      try {
        const ctx = await initContext();
        const allTasks = await loadAllTasks(ctx);
        const items = await loadAllItems(ctx);

        // Load meta items if filtering by meta-ref
        const { loadMetaContext } = await import("../../parser/meta.js");
        const metaContext = await loadMetaContext(ctx);
        const allMetaItems = [
          ...metaContext.agents,
          ...metaContext.workflows,
          ...metaContext.conventions,
          ...metaContext.observations,
        ];

        const index = new ReferenceIndex(allTasks, items, allMetaItems);

        let taskList = allTasks;

        // Apply filters
        if (options.status) {
          taskList = taskList.filter((t) => t.status === options.status);
        }
        if (options.type) {
          taskList = taskList.filter((t) => t.type === options.type);
        }
        if (options.tag) {
          taskList = taskList.filter((t) => t.tags.includes(options.tag));
        }
        if (options.metaRef) {
          const metaRefResult = index.resolve(options.metaRef);
          if (!metaRefResult.ok) {
            error(errors.reference.metaRefNotFound(options.metaRef));
            process.exit(EXIT_CODES.NOT_FOUND);
          }
          const targetRef = options.metaRef.startsWith("@")
            ? options.metaRef
            : `@${options.metaRef}`;
          taskList = taskList.filter(
            (t) => t.meta_ref === targetRef || t.meta_ref === options.metaRef,
          );
        }
        if (options.grep) {
          taskList = taskList.filter((t) => {
            const match = grepItem(
              t as unknown as Record<string, unknown>,
              options.grep,
            );
            return match !== null;
          });
        }

        output(taskList, () =>
          formatTaskList(
            taskList,
            options.verbose,
            index,
            options.grep,
            options.full,
          ),
        );
      } catch (err) {
        error(errors.failures.listTasks, err);
        process.exit(EXIT_CODES.ERROR);
      }
    });

  // kspec task get <ref>
  task
    .command("get <ref>")
    .description("Get task details")
    .action(async (ref: string) => {
      try {
        const ctx = await initContext();
        const tasks = await loadAllTasks(ctx);
        const _items = await loadAllItems(ctx);

        // Build all indexes including TraitIndex
        const { refIndex: index, traitIndex } = await (async () => {
          const { buildIndexes } = await import("../../parser/index.js");
          return buildIndexes(ctx);
        })();

        const foundTask = resolveTaskRef(ref, tasks, index);

        // AC: @trait-display ac-3 - task get shows inherited AC sections
        // Get inherited traits if task has spec_ref
        let inheritedTraits: Array<{
          trait: {
            ulid: string;
            slug: string;
            title: string;
            description?: string;
          };
          acs: Array<{
            id: string;
            given?: string;
            when?: string;
            then?: string;
          }>;
        }> = [];
        if (foundTask.spec_ref) {
          const specResult = index.resolve(foundTask.spec_ref);
          if (specResult.ok) {
            const specUlid = specResult.ulid;
            const inheritedAC = traitIndex.getInheritedAC(specUlid);
            const traitsByTrait = new Map<
              string,
              {
                trait: (typeof inheritedAC)[0]["trait"];
                acs: Array<{
                  id: string;
                  given?: string;
                  when?: string;
                  then?: string;
                }>;
              }
            >();
            for (const { trait, ac } of inheritedAC) {
              if (!traitsByTrait.has(trait.ulid)) {
                traitsByTrait.set(trait.ulid, { trait, acs: [] });
              }
              traitsByTrait.get(trait.ulid)?.acs.push(ac);
            }
            inheritedTraits = Array.from(traitsByTrait.values());
          }
        }

        // Build JSON output with inherited traits (AC: @trait-display ac-2)
        const jsonOutput = {
          ...foundTask,
          ...(inheritedTraits.length > 0 && {
            inherited_traits: inheritedTraits.map(({ trait, acs }) => ({
              ref: `@${trait.slug}`,
              title: trait.title,
              acceptance_criteria: acs,
            })),
          }),
        };

        output(jsonOutput, () => {
          formatTaskDetails(foundTask, index);

          // AC: @trait-display ac-3, ac-4, ac-5 - Show inherited AC per trait in labeled sections
          if (inheritedTraits.length > 0) {
            for (const { trait, acs } of inheritedTraits) {
              console.log(
                chalk.gray(`\n─── Inherited from @${trait.slug} ───`),
              );
              for (const ac of acs) {
                console.log(
                  chalk.cyan(`  [${ac.id}]`) +
                    chalk.gray(` (from @${trait.slug})`),
                );
                if (ac.given) console.log(`    Given: ${ac.given}`);
                if (ac.when) console.log(`    When: ${ac.when}`);
                if (ac.then) console.log(`    Then: ${ac.then}`);
              }
            }
          }
        });
      } catch (err) {
        error(errors.failures.getTask, err);
        process.exit(EXIT_CODES.ERROR);
      }
    });

  // kspec task add
  task
    .command("add")
    .description("Create a new task")
    .requiredOption("--title <title>", "Task title")
    .option("--description <description>", "Task description")
    .option(
      "--type <type>",
      "Task type (task, epic, bug, spike, infra)",
      "task",
    )
    .option("--spec-ref <ref>", "Reference to spec item")
    .option(
      "--meta-ref <ref>",
      "Reference to meta item (workflow, agent, or convention)",
    )
    .option("--plan-ref <ref>", "Reference to plan this task is derived from")
    .option("--priority <n>", "Priority (1-5)", "3")
    .option("--slug <slug>", "Human-friendly slug")
    .option("--tag <tag...>", "Tags")
    .option("--depends-on <refs...>", "Set task dependencies")
    .option(
      "--automation <status>",
      "Automation eligibility (eligible, needs_review, manual_only)",
    )
    .addHelpText(
      "after",
      `
Examples:
  $ kspec task add --title "Implement feature" --spec-ref @feature-spec
  $ kspec task add --title "Fix bug" --type bug --priority 1
  $ kspec task add --title "Multi-tag task" --tag cli urgent`,
    )
    .action(async (options) => {
      try {
        const ctx = await initContext();
        const tasks = await loadAllTasks(ctx);
        const items = await loadAllItems(ctx);

        // Load meta items for validation
        const { loadMetaContext } = await import("../../parser/meta.js");
        const metaContext = await loadMetaContext(ctx);
        const allMetaItems = [
          ...metaContext.agents,
          ...metaContext.workflows,
          ...metaContext.conventions,
          ...metaContext.observations,
        ];

        // Build index for reference validation
        const refIndex = new ReferenceIndex(tasks, items, allMetaItems);

        // Check slug uniqueness if provided
        if (options.slug) {
          const slugCheck = checkSlugUniqueness(refIndex, [options.slug]);
          if (!slugCheck.ok) {
            error(
              errors.slug.alreadyExists(slugCheck.slug, slugCheck.existingUlid),
            );
            process.exit(EXIT_CODES.CONFLICT);
          }
        }

        // Validate meta_ref if provided (AC-meta-ref-3, AC-meta-ref-4)
        if (options.metaRef) {
          const metaRefResult = refIndex.resolve(options.metaRef);

          if (!metaRefResult.ok) {
            error(errors.reference.metaRefNotFound(options.metaRef));
            process.exit(EXIT_CODES.NOT_FOUND);
          }

          // Check if the resolved item is a meta item (not a spec item or task)
          const isTask = tasks.some((t) => t._ulid === metaRefResult.ulid);
          const isSpecItem = items.some((i) => i._ulid === metaRefResult.ulid);

          if (isTask || isSpecItem) {
            error(errors.reference.metaRefPointsToSpec(options.metaRef));
            process.exit(EXIT_CODES.NOT_FOUND);
          }
        }

        // AC: @task-automation-eligibility ac-13 - validate automation if provided
        let automationValue:
          | "eligible"
          | "needs_review"
          | "manual_only"
          | undefined;
        if (options.automation) {
          const validStatuses = ["eligible", "needs_review", "manual_only"];
          if (!validStatuses.includes(options.automation)) {
            error(
              `Invalid automation status: ${options.automation}. Must be one of: ${validStatuses.join(", ")}`,
            );
            process.exit(EXIT_CODES.VALIDATION_FAILED);
          }
          automationValue = options.automation as
            | "eligible"
            | "needs_review"
            | "manual_only";
        }

        // Validate plan_ref if provided (AC: @plan-derive ac-5, ac-6)
        if (options.planRef) {
          const { loadPlans } = await import("../../parser/plans.js");
          const plans = await loadPlans(ctx);

          const planResult = refIndex.resolve(options.planRef);
          if (!planResult.ok) {
            error(`Plan reference not found: ${options.planRef}`);
            process.exit(EXIT_CODES.NOT_FOUND);
          }

          // Check if the resolved item is a plan (not a task or spec item)
          const isTask = tasks.some((t) => t._ulid === planResult.ulid);
          const isSpecItem = items.some((i) => i._ulid === planResult.ulid);
          const isPlan = plans.some((p) => p._ulid === planResult.ulid);

          if (isTask || isSpecItem || !isPlan) {
            error(`Reference "${options.planRef}" is not a plan`);
            process.exit(EXIT_CODES.NOT_FOUND);
          }
        }

        // AC: @task-add-depends-on ac-2 - Validate dependency refs
        if (options.dependsOn) {
          for (const depRef of options.dependsOn) {
            const depResult = refIndex.resolve(depRef);
            if (!depResult.ok) {
              error(errors.reference.depNotFound(depRef));
              process.exit(EXIT_CODES.NOT_FOUND);
            }
            // Ensure the dependency is a task, not a spec item
            const isTask = tasks.some((t) => t._ulid === depResult.ulid);
            if (!isTask) {
              error(`Reference "${depRef}" is not a task`);
              process.exit(EXIT_CODES.NOT_FOUND);
            }
          }
        }

        // AC: @spec-task-add-description ac-6 - Omit description if empty string
        const descriptionValue =
          options.description && options.description.trim() !== ""
            ? options.description
            : undefined;

        const input: TaskInput = {
          title: options.title,
          description: descriptionValue,
          type: options.type,
          spec_ref: options.specRef || null,
          meta_ref: options.metaRef || null,
          plan_ref: options.planRef || null,
          priority: parseInt(options.priority, 10),
          slugs: options.slug ? [options.slug] : [],
          tags: options.tag || [],
          depends_on: options.dependsOn || [],
          automation: automationValue,
        };

        const newTask = createTask(input);
        await saveTask(ctx, newTask);
        await commitIfShadow(
          ctx.shadow,
          "task-add",
          newTask.slugs[0] || newTask._ulid.slice(0, 8),
          newTask.title,
        );

        // Build index including the new task for accurate short ULID
        const index = new ReferenceIndex(
          [...tasks, newTask],
          items,
          allMetaItems,
        );
        success(`Created task: ${index.shortUlid(newTask._ulid)}`, {
          task: newTask,
        });
      } catch (err) {
        error(errors.failures.createTask, err);
        process.exit(EXIT_CODES.ERROR);
      }
    });

  // kspec task set <ref>
  task
