    const isPlan = plans.some((p) => p._ulid === planRefResult.ulid);

    if (isTask || isSpecItem || !isPlan) {
      return {
        success: false,
        error: `Reference "${options.planRef}" is not a plan`,
      };
    }

    updatedTask.plan_ref = options.planRef;
    changes.push("plan_ref");
  }
}

if (options.priority) {
